<style>
/* one small gesture per desk, 0 / 60 / 100 / 130 ms; heads stay still */
  .block { animation: lift 300ms var(--ease-out) both; }
  @keyframes lift { from { translate: 0 6px; } }
  .lens { animation: lens 600ms var(--ease-stage) 60ms both; }
  @keyframes lens { from { translate: -18px 0; } }
  .scan { animation: scan 300ms var(--ease-out) 100ms both; }
  @keyframes scan { from { translate: 0 -22px; opacity: 0; } }
  .check { transform-box: fill-box; transform-origin: center; animation: check 150ms var(--ease-out) 400ms both; }
  @keyframes check { from { scale: 0.6; opacity: 0; } }
  .l1, .l2, .l3, .l4 { --dur: 300ms; }
  .l1 { --d: 130ms; } .l2 { --d: 190ms; } .l3 { --d: 230ms; } .l4 { --d: 260ms; }
</style>
